    static void all(ServerMatch m,boolean expected){for(UUID p:List.of(A,B)){check(has(m,p,active(m,p))==expected,"Wrong Active suppression");for(var mon:m.benchPokemonView(p))check(has(m,p,mon.pokemonId())==expected,"Wrong Bench suppression");}}
    static ServerMatch aiGame(String id){var c=new GeneratedRuleBatch28Test.Config();c.trainer=profile();c.ownAbility=NonPokemonBatch105Test.draw();c.attack=GeneratedRuleBatch8Test.hit(200,false);c.defenderAttack=c.attack;return GeneratedRuleBatch28Test.fixture(c);}
    public static void main(String[] args){scopeAndOverlap();extraTurns();immunity();boundaries();priorEffects();handAndDiscard();deckEntry();ai();schema();System.out.println("NonPokemonBatch106Test passed: Hex Maniac both fields/hand/discard, evolution and actual opposing-turn expiry including extra/overlapping turns, existing versus later immunity and erased guarding source, turn-end/Checkup timing, existing resolved effects, hand placement/Ho-Oh/discard counts and deck-entry exclusion, four AI difficulties");}
    static void scopeAndOverlap(){for(boolean overlap:List.of(false,true)){var m=game();play(m,A);all(m,false);check(m.activeRetreatCost(A)==3&&m.activeRetreatCost(B)==3,"Hex left passive modifiers");m.endTurn(A);settle(m);all(m,false);UUID host=active(m,B);m.evolveByEffect(B,host,hand(m,B,"evolved").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);all(m,false);m.switchActiveByEffect(B,B,bench(m,B));all(m,false);if(overlap)play(m,B);m.endTurn(B);settle(m);all(m,!overlap);if(overlap){m.endTurn(A);settle(m);all(m,true);}}}
    static void extraTurns(){for(boolean ownExtra:List.of(false,true)){
        var attack=BeforeDamageAttackTest.attack("","","{\"type\":\"extra_turn\",\"target\":\"SELF\",\"skip_checkup\":true}").withUsageLimit(new SharedUsageLimit(SharedUsageLimit.GX,SharedUsageLimit.Period.GAME));
        var m=game(List.of(NonPokemonBatch105Test.draw()),attack);play(m,A);if(!ownExtra)m.endTurn(A);UUID actor=m.currentPlayer();m.attack(actor,"hit");settle(m);check(m.currentPlayer().equals(actor),"Extra turn fixture failed");all(m,!ownExtra);
        if(ownExtra){m.endTurn(A);all(m,false);m.endTurn(B);all(m,true);}
    }}
    static void immunity(){var guard=NonPokemonBatch2Test.DATA.pokemon("sv6-5_en_045").orElseThrow().ability("unnerve").orElseThrow();var m=game(List.of(guard,NonPokemonBatch105Test.draw()),GeneratedRuleBatch8Test.hit(40,false));play(m,A);check(!has(m,A,active(m,A))&&has(m,B,active(m,B))&&has(m,B,bench(m,B)),"Hex ignored existing self immunity or applied own opponent guard");m.endTurn(A);m.evolveByEffect(B,bench(m,B),hand(m,B,"evolved").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);check(!has(m,B,bench(m,B)),"New evolved Unnerve escaped established Hex");m.devolvePokemonToHandByEffect(B,B,bench(m,B));check(!has(m,B,bench(m,B)),"Devolving resurrected a stale immunity snapshot");
        var wall=DiscardAbilityCountTest.passive("active-wall","{\"type\":\"passive_effect_guard\",\"target\":\"OWN_BENCH\",\"source\":\"TRAINER\",\"from\":\"OPPONENT\",\"scope\":\"EFFECTS_ONLY\",\"trainer_categories\":\"SUPPORTER\",\"source_active_only\":true}");
        var erased=game(List.of(wall,NonPokemonBatch105Test.draw()),GeneratedRuleBatch8Test.hit(40,false));play(erased,A);all(erased,false);
    }
    static void boundaries(){var m=game(List.of(NonPokemonBatch105Test.boundary("ON_TURN_END"),NonPokemonBatch105Test.boundary("ON_POKEMON_CHECKUP")),GeneratedRuleBatch8Test.hit(40,false));for(UUID p:List.of(A,B))m.attachEnergyByEffect(A,p,EffectSourceZone.HAND,hand(m,p,"special").instanceId(),p,active(m,p));play(m,A);int ah=m.privateView(A).hand().size(),bh=m.privateView(B).hand().size();m.endTurn(A);settle(m);check(m.privateView(A).hand().size()==ah&&m.privateView(B).hand().size()==bh+1,"Hex expired at own turn/checkup");m.endTurn(B);settle(m);check(m.privateView(A).hand().size()==ah+2&&m.privateView(B).hand().size()==bh+2,"Hex ending opponent turn should suppress end events, then restore Checkup");}
    static void priorEffects(){var shield=ResumableAbilityTest.ability("shield",EffectOriginProtectionTest.shield("ATTACK","DAMAGE_AND_EFFECTS","SELF","LEAVES_PLAY"));var m=game(List.of(shield),GeneratedRuleBatch8Test.hit(40,false));m.useAbility(A,active(m,A),"shield");play(m,A);all(m,false);m.endTurn(A);m.attack(B,"hit");settle(m);check(m.activePokemonView(A).damage()==0,"Hex erased an already resolved Ability effect");}
    static PokemonProfile custom(String from,PokemonPlacementRule placement){return new PokemonProfile(1000,0,from,null,0,null,0,1,List.of(GeneratedRuleBatch8Test.hit(100,false)),List.of(NonPokemonBatch105Test.draw()),EnergyType.COLORLESS,null,null,placement);}
    static ServerMatch zones(){return zones(profile());}
    static ServerMatch zones(TrainerProfile trainer){
        var profiles=new LinkedHashMap<String,PokemonProfile>();profiles.put("base",custom(null,PokemonPlacementRule.ANY_EFFECT));profiles.put("stage1",custom("base",PokemonPlacementRule.ANY_EFFECT));profiles.put("stage2",custom("stage1",PokemonPlacementRule.ANY_EFFECT));profiles.put("rotator",custom("stage1",PokemonPlacementRule.EMERGENCY_ROTATION));profiles.put("flash",custom("stage1",PokemonPlacementRule.SWELLING_FLASH));profiles.put("reviver",NonPokemonBatch2Test.DATA.pokemon("swsh12_en_140").orElseThrow());profiles.put("entry",NonPokemonBatch2Test.DATA.pokemon("swsh12_en_119").orElseThrow());
        var kinds=List.of("base","base","base","base","base","stage1","stage2","rotator","flash","reviver","entry","energy","energy","trainer","trainer");var defs=new ArrayList<CardDefinition>();for(String key:new LinkedHashSet<>(kinds))defs.add(new CardDefinition(key,key,key.equals("trainer")?CardCategory.TRAINER:key.equals("energy")?CardCategory.ENERGY:CardCategory.POKEMON,key.equals("trainer")?trainer.category():TrainerCategory.NONE,"H",Set.of("international"),Set.of("base","reviver").contains(key),key.equals("energy"),60,Map.of(),EffectSupport.SUPPORTED,null));
        var combat=new CombatCatalog(profiles,Map.of("energy",EnergyType.FIRE),Map.of("trainer",trainer));
        for(int seed=seedHint;seed<seedHint+1000;seed++){var decks=new ArrayList<List<CardInstance>>();for(UUID p:List.of(A,B)){var cards=new ArrayList<CardInstance>();for(int i=0;i<60;i++)cards.add(new CardInstance(new UUID(p.getLeastSignificantBits(),i+1),p,kinds.get(i%kinds.size())));decks.add(cards);}var m=new ServerMatch(A,B,decks.get(0),decks.get(1),GeneratedRuleBatch8Test.RULES,new CardDatabase(defs),combat,new ServerRandom(seed));OpeningTestSupport.decideOrder(m,A,B);if(List.of(A,B).stream().anyMatch(p->m.privateView(p).hand().stream().filter(c->c.definitionId().equals("base")).count()<2))continue;
            for(UUID p:List.of(A,B)){var bs=m.privateView(p).hand().stream().filter(c->c.definitionId().equals("base")).toList();m.chooseOpeningActive(p,bs.getFirst().instanceId());m.placeOpeningBench(p,bs.get(1).instanceId());m.startAfterOpening(p);}OpeningTestSupport.complete(m,A,B,1);if(m.hasPendingEmergencyEntry())m.decideEmergencyEntry(m.currentPlayer(),false);m.drawCardsByEffect(A,A,23);m.drawCardsByEffect(A,B,23);
            if(List.of(A,B).stream().anyMatch(p->new LinkedHashSet<>(kinds).stream().anyMatch(k->m.privateView(p).hand().stream().noneMatch(c->c.definitionId().equals(k)))||m.privateView(p).deck().stream().noneMatch(c->c.definitionId().equals("base"))))continue;
            DeckDiscardTriggeredAbilityTest.top(m,B,"base");m.endTurn(A);DeckDiscardTriggeredAbilityTest.top(m,A,"base");m.endTurn(B);seedHint=seed;return m;
        }throw new AssertionError("Hex zone fixture unavailable");
    }
    static void handAndDiscard(){var m=zones();UUID host=bench(m,A);m.evolveByEffect(A,host,hand(m,A,"stage1").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);m.evolveByEffect(A,host,hand(m,A,"stage2").instanceId(),EvolutionPermission.CARD_EFFECT_ALL_TIMING);
        var prize=PairedTrainerPlayTest.zone(m,A,"prizes").removeLast();PairedTrainerPlayTest.zone(m,A,"hand").add(prize);var reviver=hand(m,B,"reviver");m.discardHandCardsByEffect(A,B,List.of(reviver.instanceId()));m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);m.endTurn(A);if(m.hasPendingEmergencyEntry())m.decideEmergencyEntry(B,false);
        check(!m.canUseEmergencyRotation(B,hand(m,B,"rotator").instanceId())&&!m.canUseSwellingFlash(B,hand(m,B,"flash").instanceId())&&!m.canUseDiscardAbility(B,reviver.instanceId(),"reviving-flame"),"Hex left hand/discard activations available");check(!m.matchesEffectCondition(B,active(m,B),new ConditionDefinition(ConditionType.DISCARD_COUNT,Map.of("ability_id","reviving-flame","value","1","comparison",">="),List.of())),"Discard ability count ignored Hex");m.endTurn(B);if(m.hasPendingEmergencyEntry())m.decideEmergencyEntry(A,false);m.endTurn(A);if(m.hasPendingEmergencyEntry())m.decideEmergencyEntry(B,false);
        check(m.canUseEmergencyRotation(B,hand(m,B,"rotator").instanceId())&&m.canUseSwellingFlash(B,hand(m,B,"flash").instanceId())&&m.canUseDiscardAbility(B,reviver.instanceId(),"reviving-flame"),"Hand/discard abilities failed expiry restoration");check(m.matchesEffectCondition(B,active(m,B),new ConditionDefinition(ConditionType.DISCARD_COUNT,Map.of("ability_id","reviving-flame","value","1","comparison",">="),List.of())),"Discard ability count failed restoration");
    }
    static void deckEntry(){var m=zones();var card=hand(m,B,"entry");PairedTrainerPlayTest.zone(m,B,"hand").remove(card);PairedTrainerPlayTest.zone(m,B,"deck").add(card);m.playTrainer(A,hand(m,A,"trainer").instanceId(),null);m.endTurn(A);check(m.hasPendingEmergencyEntry(B),"Hex wrongly erased a deck-before-draw Ability");int hand=m.privateView(B).hand().size();m.decideEmergencyEntry(B,true);settle(m);check(m.benchPokemonView(B).stream().anyMatch(p->p.topCardId().equals("entry"))&&m.privateView(B).hand().size()==hand+3,"Top Entry failed under Hex");}
    static void ai(){for(var level:AiDifficulty.values()){var m=aiGame(IDS.getFirst());UUID p=m.currentPlayer();m.playTrainer(p,hand(m,p,"trainer").instanceId(),null);var ps=NonPokemonBatch103Test.seats(m);var s=MatchSession.multiplayer(m,ps.get(0),ps.get(1));AiCardOperationTest.settle(s,level);AiCardOperationTest.finish(s,level);check(m.phase()==MatchPhase.FINISHED,"Hex AI stalled");}}
    static void schema(){var e=profile().effectProgram().triggers().getFirst().effects().getFirst();var a=new HashMap<>(e.arguments());a.put("scope","ALL_ZONES");GeneratedRuleBatch8Test.reject(()->TurnAbilitySuppression.validate(new EffectDefinition(e.type(),e.target(),a,List.of(),List.of())));}
